import{_ as o,o as a,c as r,a4 as e}from"./chunks/framework.9tZL7ZIQ.js";const _=JSON.parse('{"title":"管理准则","description":"","frontmatter":{},"headers":[],"relativePath":"09_books/巴菲特之道/准则/02_管理准则.md","filePath":"09_books/巴菲特之道/准则/02_管理准则.md"}'),l={name:"09_books/巴菲特之道/准则/02_管理准则.md"};function n(s,t,i,p,h,c){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="管理准则" tabindex="-1">管理准则 <a class="header-anchor" href="#管理准则" aria-label="Permalink to &quot;管理准则&quot;">​</a></h1><p>优秀的管理层是巴菲特投资决策的重要组成部分。他寻找的是既能干又为股东着想的管理层。</p><h2 id="三大管理准则" tabindex="-1">三大管理准则 <a class="header-anchor" href="#三大管理准则" aria-label="Permalink to &quot;三大管理准则&quot;">​</a></h2><h3 id="_1-理性" tabindex="-1">1. 理性 <a class="header-anchor" href="#_1-理性" aria-label="Permalink to &quot;1. 理性&quot;">​</a></h3><blockquote><p><strong>&quot;理性是区分伟大管理者与普通管理者的关键。&quot;</strong></p></blockquote><p>理性的管理层能够将公司盈余资金进行有效配置，在有利可图时投资，在股价被低估时回购。</p><p><strong>核心要点：</strong></p><ul><li>理性配置资本</li><li>在股价低估时回购股票</li><li>在有吸引力的机会时进行收购</li></ul><p><strong>相关阅读：</strong> <a href="/02_concepts/capital-allocation.html">资本配置</a></p><hr><h3 id="_2-坦诚" tabindex="-1">2. 坦诚 <a class="header-anchor" href="#_2-坦诚" aria-label="Permalink to &quot;2. 坦诚&quot;">​</a></h3><blockquote><p><strong>&quot;管理层应该对股东坦诚相待。&quot;</strong></p></blockquote><p>巴菲特欣赏那些勇于承认错误、不时报喜也报忧的管理层。</p><p><strong>核心要点：</strong></p><ul><li>直接承认失误</li><li>透明披露公司状况</li><li>不做财务操纵</li></ul><p><strong>相关阅读：</strong> <a href="/02_concepts/reputation.html">声誉经济</a></p><hr><h3 id="_3-独立思考" tabindex="-1">3. 独立思考 <a class="header-anchor" href="#_3-独立思考" aria-label="Permalink to &quot;3. 独立思考&quot;">​</a></h3><blockquote><p><strong>&quot;惯性驱使是管理层的天敌。&quot;</strong></p></blockquote><p>管理层往往倾向于随大流，做与其他公司相同的事情。优秀的领导者能够抵抗这种惯性。</p><p><strong>核心要点：</strong></p><ul><li>不盲目模仿竞争对手</li><li>敢于做出逆向决策</li><li>坚持长期正确的事</li></ul><p><strong>相关阅读：</strong> <a href="/02_concepts/contrarian.html">逆向思维</a></p><hr><h2 id="案例-喜诗糖果" tabindex="-1">案例：喜诗糖果 <a class="header-anchor" href="#案例-喜诗糖果" aria-label="Permalink to &quot;案例：喜诗糖果&quot;">​</a></h2><p>1972年收购喜诗糖果后，巴菲特对管理层的要求体现了这三大准则：</p><ul><li><strong>理性</strong>：管理层严格控制成本</li><li><strong>坦诚</strong>：每年如实报告业绩</li><li><strong>独立思考</strong>：不为短期利益牺牲品质</li></ul><p><strong>相关阅读：</strong> <a href="/03_companies/喜诗糖果.html">喜诗糖果</a></p><hr><h2 id="巴菲特对管理层的评价标准" tabindex="-1">巴菲特对管理层的评价标准 <a class="header-anchor" href="#巴菲特对管理层的评价标准" aria-label="Permalink to &quot;巴菲特对管理层的评价标准&quot;">​</a></h2><p>在致股东信中，巴菲特多次强调：</p><blockquote><p><strong>&quot;我们寻找的是那些既能干又为股东着想的管理层。&quot;</strong></p></blockquote><p><strong>相关阅读：</strong> <a href="/02_concepts/management.html">管理层选择</a></p>',33)])])}const d=o(l,[["render",n]]);export{_ as __pageData,d as default};
